/**
 * The public-mode hidden set (2026-10-19 owner decree; Step 3 §2.2 AC-08 +
 * T-15 + LR-02): data/site-mode-overrides.json is GENERATED by the registry
 * generator — this test pins it against the audit sidecar so the two files
 * can never drift (a new 'no' verdict MUST appear in the hidden set before
 * a SITE_MODE=public build can pass T-15, and a re-verified 'yes' MUST
 * leave it, or a public card silently disappears).
 */
import { readFileSync } from 'node:fs';
import { describe, expect, it } from 'vitest';
import { IndicatorIdSchema } from '@currena/core';

const dataRoot = new URL('../../../data/', import.meta.url);

describe('data/site-mode-overrides.json (the generated public-mode hidden set)', () => {
  const overrides = JSON.parse(readFileSync(new URL('site-mode-overrides.json', dataRoot), 'utf8')) as {
    version: number;
    hiddenIndicatorIds: string[];
    hiddenBoards: string[];
  };
  const audit = JSON.parse(readFileSync(new URL('indicator-audit.json', dataRoot), 'utf8')) as {
    indicators: { id: string; publicDisplayOk: string }[];
  };

  it('hides EXACTLY the indicators whose publicDisplayOk is not yes (fail-closed unknowns included)', () => {
    const mustHide = audit.indicators.filter((i) => i.publicDisplayOk !== 'yes').map((i) => i.id).sort();
    expect(overrides.hiddenIndicatorIds).toEqual(mustHide);
  });

  it('hides NEITHER world board — markets rides the 2026-10-18b directive, fx the 2026-10-21c restoration directive', () => {
    // The world MARKETS board is the owner's 2026-10-18b directive (their
    // own EODHD key backs it) and the world FX board the owner's
    // 2026-10-21c currencies-restoration directive (ECB reference rates
    // via Frankfurter — the same rates the public converter displays;
    // terms verified 2026-10-21): a generator change must never re-hide
    // either without the owner saying so, and both directives' evidence
    // notes must ride in the generated file.
    expect(overrides.hiddenBoards).toEqual([]);
    const directives = (overrides as { ownerBoardDirectives?: Record<string, string> }).ownerBoardDirectives ?? {};
    for (const board of ['markets', 'fx']) {
      const note = directives[board];
      expect(typeof note).toBe('string');
      expect((note ?? '').length).toBeGreaterThan(0);
    }
  });

  it('keeps the 2026-10-19e owner-directive prices tiles PUBLIC (gold, silver, bitcoin, brent)', () => {
    // The owner restored the prices board explicitly (it displayed publicly
    // before the rebuild); a generator change must never re-hide these four.
    for (const id of ['brent', 'gold-usd', 'silver-usd', 'btc-usd']) {
      expect(overrides.hiddenIndicatorIds).not.toContain(id);
      expect(audit.indicators.find((i) => i.id === id)?.publicDisplayOk).toBe('yes');
    }
  });

  it('only hides KNOWN indicator ids (a stale rename must fail loudly here)', () => {
    for (const id of overrides.hiddenIndicatorIds) {
      expect(() => IndicatorIdSchema.parse(id)).not.toThrow();
    }
  });
});
